/**
 * Manual routing state machine and utilities.
 *
 * States: idle → routing (on pad click) → idle (on pad click / Escape)
 *
 * While routing, the user sees a preview trace following the cursor
 * with 45°/90° snapping and live DRC violation overlay.
 */

import type { ComponentInfo, PadInfo, TraceSegmentInfo, ViolationInfo, BoardSnapshot } from './types';
import type { PcbEngine } from './wasm';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type RoutingMode = 'idle' | 'routing';

export interface RoutingState {
  mode: RoutingMode;
  /** Pad that started the route (null when idle) */
  startPad: PadHit | null;
  /** Current copper layer name ('Top' | 'Bottom') */
  currentLayer: string;
  /** World-coordinate anchor for the current segment (nm) */
  anchorPoint: { x: number; y: number };
  /** Completed segments so far (anchor→anchor for multi-click routes) */
  committedSegments: TraceSegmentInfo[];
  /** Preview segment from last anchor to snapped cursor (shown as dashed) */
  previewSegment: TraceSegmentInfo | null;
  /** Snap angle in degrees (0, 45, 90, …) applied to the preview */
  snapAngle: number;
  /** Net name being routed (from start pad) */
  netName: string;
  /** DRC violations detected during preview (live feedback) */
  drcViolations: ViolationInfo[];
  /** Trace width in nm (default 250_000 = 0.25mm) */
  traceWidth: number;
  /** Whether grid snap is active */
  gridSnapEnabled: boolean;
  /** Grid spacing in nm (default 1_270_000 = 1.27mm = 50mil) */
  gridSpacing: number;
}

export interface PadHit {
  component: ComponentInfo;
  pad: PadInfo;
  /** Pad center in world coordinates (nm) */
  worldX: number;
  worldY: number;
  /** Net this pad belongs to (empty string if unknown) */
  netName: string;
}

// ---------------------------------------------------------------------------
// Initial state
// ---------------------------------------------------------------------------

export function createRoutingState(): RoutingState {
  return {
    mode: 'idle',
    startPad: null,
    currentLayer: 'Top',
    anchorPoint: { x: 0, y: 0 },
    committedSegments: [],
    previewSegment: null,
    snapAngle: 0,
    netName: '',
    drcViolations: [],
    traceWidth: 250_000, // 0.25mm default
    gridSnapEnabled: false,
    gridSpacing: 1_270_000, // 1.27mm = 50mil default
  };
}

// ---------------------------------------------------------------------------
// Pad hit-testing
// ---------------------------------------------------------------------------

/**
 * Compute pad center in world coordinates, accounting for component rotation.
 */
function padWorldPosition(comp: ComponentInfo, pad: PadInfo): [number, number] {
  const radians = (comp.rotation_mdeg / 1000) * (Math.PI / 180);
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);
  const rx = pad.x_nm * cos - pad.y_nm * sin;
  const ry = pad.x_nm * sin + pad.y_nm * cos;
  return [comp.x_nm + rx, comp.y_nm + ry];
}

/**
 * Find the pad closest to a world-coordinate point, within tolerance.
 *
 * @param snapshot   Current board snapshot
 * @param worldX     Click position in nm
 * @param worldY     Click position in nm
 * @param toleranceNm  Hit radius in nm
 * @returns The closest pad or null
 */
export function hitTestPad(
  snapshot: BoardSnapshot | null,
  worldX: number,
  worldY: number,
  toleranceNm: number,
): PadHit | null {
  if (!snapshot) return null;

  let bestDist = Infinity;
  let bestHit: PadHit | null = null;

  for (const comp of snapshot.components) {
    for (const pad of comp.pads) {
      const [px, py] = padWorldPosition(comp, pad);
      const dx = worldX - px;
      const dy = worldY - py;
      const dist = Math.sqrt(dx * dx + dy * dy);

      // Tolerance is the explicit radius PLUS half the pad diagonal
      const padRadius = Math.sqrt(pad.width_nm * pad.width_nm + pad.height_nm * pad.height_nm) / 2;
      if (dist <= padRadius + toleranceNm && dist < bestDist) {
        bestDist = dist;

        // Find which net this pad belongs to
        const pinRef = `${comp.refdes}.${pad.number}`;
        let netName = '';
        for (const net of snapshot.nets) {
          if (net.connections.some(c => `${c.component}.${c.pin}` === pinRef)) {
            netName = net.name;
            break;
          }
        }

        bestHit = { component: comp, pad, worldX: px, worldY: py, netName };
      }
    }
  }

  return bestHit;
}

// ---------------------------------------------------------------------------
// Grid snapping
// ---------------------------------------------------------------------------

/**
 * Snap a point to the nearest grid intersection.
 * Grid origin is (0, 0). Spacing is in nm.
 */
export function snapToGrid(
  point: { x: number; y: number },
  spacing: number,
): { x: number; y: number } {
  return {
    x: Math.round(point.x / spacing) * spacing,
    y: Math.round(point.y / spacing) * spacing,
  };
}

// ---------------------------------------------------------------------------
// Angle snapping
// ---------------------------------------------------------------------------

/** Allowed snap angles in degrees */
const SNAP_ANGLES_DEG = [0, 45, 90, 135, 180, 225, 270, 315];

/**
 * Snap a cursor point to the nearest 45°/90° angle from an anchor.
 * Returns the snapped world-coordinate endpoint and the angle used.
 */
export function computeSnappedPoint(
  anchor: { x: number; y: number },
  cursor: { x: number; y: number },
): { x: number; y: number; angleDeg: number } {
  const dx = cursor.x - anchor.x;
  const dy = cursor.y - anchor.y;
  const distance = Math.sqrt(dx * dx + dy * dy);

  if (distance < 1) {
    return { x: anchor.x, y: anchor.y, angleDeg: 0 };
  }

  // Angle from anchor to cursor (degrees, 0 = right, counter-clockwise)
  const rawAngleDeg = (Math.atan2(dy, dx) * 180) / Math.PI;
  // Normalize to 0-360
  const normalAngle = ((rawAngleDeg % 360) + 360) % 360;

  // Find closest snap angle
  let bestAngle = 0;
  let bestDiff = 360;
  for (const snap of SNAP_ANGLES_DEG) {
    let diff = Math.abs(normalAngle - snap);
    if (diff > 180) diff = 360 - diff;
    if (diff < bestDiff) {
      bestDiff = diff;
      bestAngle = snap;
    }
  }

  const radians = (bestAngle * Math.PI) / 180;
  return {
    x: anchor.x + distance * Math.cos(radians),
    y: anchor.y + distance * Math.sin(radians),
    angleDeg: bestAngle,
  };
}

// ---------------------------------------------------------------------------
// State machine transitions
// ---------------------------------------------------------------------------

/**
 * Start a route from a pad click.
 */
export function startRoute(
  state: RoutingState,
  padHit: PadHit,
): RoutingState {
  // Detect layer from pad's layer mask
  const layer = (padHit.pad.layer_mask & 0x02) ? 'Bottom' : 'Top';

  console.log(`[Route] idle → routing: pad ${padHit.component.refdes}.${padHit.pad.number} net=${padHit.netName} layer=${layer}`);

  return {
    ...state,
    mode: 'routing',
    startPad: padHit,
    currentLayer: layer,
    anchorPoint: { x: padHit.worldX, y: padHit.worldY },
    committedSegments: [],
    previewSegment: null,
    snapAngle: 0,
    netName: padHit.netName,
    drcViolations: [],
  };
}

/**
 * Update the preview segment during mouse move (while routing).
 * When grid snap is enabled, the cursor is snapped to grid first,
 * then angle snap is applied from the anchor to the grid-snapped point.
 */
export function updatePreview(
  state: RoutingState,
  cursorWorld: { x: number; y: number },
): RoutingState {
  if (state.mode !== 'routing') return state;

  // Apply grid snap first if enabled
  const gridAdjusted = state.gridSnapEnabled
    ? snapToGrid(cursorWorld, state.gridSpacing)
    : cursorWorld;

  // Then apply angle snap
  const snapped = computeSnappedPoint(state.anchorPoint, gridAdjusted);

  return {
    ...state,
    previewSegment: {
      start_x: state.anchorPoint.x,
      start_y: state.anchorPoint.y,
      end_x: snapped.x,
      end_y: snapped.y,
    },
    snapAngle: snapped.angleDeg,
  };
}

/**
 * Add a waypoint (click in empty space while routing).
 * Commits the current preview segment and starts a new one from the endpoint.
 */
export function addWaypoint(state: RoutingState): RoutingState {
  if (state.mode !== 'routing' || !state.previewSegment) return state;

  const seg = state.previewSegment;
  console.log(`[Route] waypoint at (${(seg.end_x / 1e6).toFixed(2)}, ${(seg.end_y / 1e6).toFixed(2)})mm`);

  return {
    ...state,
    committedSegments: [...state.committedSegments, seg],
    anchorPoint: { x: seg.end_x, y: seg.end_y },
    previewSegment: null,
  };
}

/**
 * Complete the route by clicking on a target pad.
 * Returns the final list of segments to add as a trace.
 */
export function completeRoute(
  state: RoutingState,
  targetPad: PadHit,
): { segments: TraceSegmentInfo[]; netName: string; layer: string; width: number } | null {
  if (state.mode !== 'routing') return null;

  // Build final segment from last anchor to target pad center
  const finalSeg: TraceSegmentInfo = {
    start_x: state.anchorPoint.x,
    start_y: state.anchorPoint.y,
    end_x: targetPad.worldX,
    end_y: targetPad.worldY,
  };

  const allSegments = [...state.committedSegments, finalSeg];

  console.log(`[Route] routing → idle: completed ${allSegments.length} segments to ${targetPad.component.refdes}.${targetPad.pad.number}`);

  return {
    segments: allSegments,
    netName: state.netName,
    layer: state.currentLayer,
    width: state.traceWidth,
  };
}

/**
 * Cancel the in-progress route.
 */
export function cancelRoute(state: RoutingState): RoutingState {
  if (state.mode !== 'routing') return state;
  console.log('[Route] routing → idle: cancelled');
  return {
    ...createRoutingState(),
    gridSnapEnabled: state.gridSnapEnabled,
    gridSpacing: state.gridSpacing,
  };
}

/**
 * Flip the active copper layer during routing (Top ↔ Bottom).
 * Called when the user presses 'F' while routing.
 */
export function flipLayer(state: RoutingState): RoutingState {
  if (state.mode !== 'routing') return state;
  const newLayer = state.currentLayer === 'Top' ? 'Bottom' : 'Top';
  console.log(`[Route] layer flip: ${state.currentLayer} → ${newLayer}`);
  return { ...state, currentLayer: newLayer };
}

/**
 * Set DRC violations on the routing state (called after debounced DRC check).
 */
export function setDrcViolations(state: RoutingState, violations: ViolationInfo[]): RoutingState {
  return { ...state, drcViolations: violations };
}

// ---------------------------------------------------------------------------
// DRC preview (debounced)
// ---------------------------------------------------------------------------

/**
 * Build the flat segment array for the preview trace (committed + preview).
 * Format: [x1,y1,x2,y2, ...] matching PcbEngine.add_trace() signature.
 */
export function previewSegmentsFlat(state: RoutingState): number[] {
  const segs = [...state.committedSegments];
  if (state.previewSegment) segs.push(state.previewSegment);
  const flat: number[] = [];
  for (const s of segs) {
    flat.push(
      Math.round(s.start_x), Math.round(s.start_y),
      Math.round(s.end_x), Math.round(s.end_y),
    );
  }
  return flat;
}

/**
 * Create a debounced DRC checker that runs at most once per `intervalMs`.
 * Adds a temporary preview trace, runs DRC, removes the trace, and calls
 * the callback with the violations detected.
 */
export function createDrcPreviewChecker(
  engine: PcbEngine,
  intervalMs: number = 100,
): {
  check: (state: RoutingState) => void;
  cancel: () => void;
  onViolations: (cb: (violations: ViolationInfo[]) => void) => void;
} {
  let timer: ReturnType<typeof setTimeout> | null = null;
  let callback: ((violations: ViolationInfo[]) => void) | null = null;

  function check(state: RoutingState): void {
    if (timer !== null) return; // Already scheduled

    timer = setTimeout(() => {
      timer = null;
      if (state.mode !== 'routing') return;

      const flat = previewSegmentsFlat(state);
      if (flat.length < 4) return;

      // Add temporary trace
      const tempId = engine.add_trace(
        state.netName,
        state.currentLayer,
        state.traceWidth,
        flat,
      );

      if (tempId === 0xFFFFFFFF) return;

      // Run DRC
      const violationCount = engine.run_drc_incremental();

      // Get violations from snapshot
      const snap = engine.get_snapshot();
      const violations = snap.violations || [];

      // Remove temporary trace
      engine.remove_trace(tempId);

      console.log(`[Route] DRC preview: ${violationCount} violations`);

      if (callback) callback(violations);
    }, intervalMs);
  }

  function cancel(): void {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function onViolations(cb: (violations: ViolationInfo[]) => void): void {
    callback = cb;
  }

  return { check, cancel, onViolations };
}

/**
 * Mouse interaction handlers for PCB viewer
 * Provides zoom, pan, and selection behaviors
 */

import type { Viewport } from './viewport';
import type { BoardSnapshot } from './types';
import type { PcbEngine } from './wasm';
import type { RoutingState } from './routing';
import { zoomAtPoint, pan, screenToWorld } from './viewport';
import { hitTestTrace } from './hit-test';
import {
  createRoutingState,
  hitTestPad,
  startRoute,
  updatePreview,
  addWaypoint,
  completeRoute,
  setDrcViolations,
  createDrcPreviewChecker,
} from './routing';
import { hitTestResizeHandle, resizeHandleCursor, type ResizeHandle } from './renderer';

export interface InteractionState {
  viewport: Viewport;
  isPanning: boolean;
  lastX: number;
  lastY: number;
  dirty: boolean;
  onSelect: (x_nm: number, y_nm: number) => void;
  onViewportChange: (vp: Viewport) => void;
  /** Current board snapshot for hit-testing */
  snapshot: BoardSnapshot | null;
  /** Currently selected trace entity ID */
  selectedTraceId: number | null;
  /** Currently hovered trace entity ID */
  hoveredTraceId: number | null;
  /** Callback when trace selection changes */
  onTraceSelect: (traceId: number | null, screenX: number, screenY: number) => void;
  /** Callback when hover trace changes */
  onTraceHover: (traceId: number | null) => void;
  /** Routing state machine */
  routing: RoutingState;
  /** PCB engine for trace mutations during routing */
  engine: PcbEngine | null;
  /** Callback when routing state changes (for re-render) */
  onRoutingChange: (routing: RoutingState) => void;
  /** Callback when a trace is added via routing (for undo stack integration) */
  onTraceAdd?: (netName: string, layer: string, width: number, segments: number[]) => void;
  /** Callback when board is resized via drag handles (for undo stack integration) */
  onBoardResize?: (oldW: number, oldH: number, newW: number, newH: number) => void;
  /** Currently active resize handle (visual feedback for renderer) */
  activeResizeHandle?: ResizeHandle | null;
}

/**
 * Set up all interaction handlers for the canvas
 * - Scroll wheel: zoom centered on cursor (also pinch-to-zoom on touchpad)
 * - Two-finger touchpad/touchscreen drag: pan
 * - Middle-click + drag: pan
 * - Ctrl + left-click + drag: pan (alternative for laptops)
 * - Left-click: select component at point
 * - Right-click: reserved (context menu prevented)
 */
export function setupInteraction(
  canvas: HTMLCanvasElement,
  state: InteractionState
): void {
  // Pointer cache for multi-touch pan detection
  const pointerCache: Array<{ pointerId: number; clientX: number; clientY: number }> = [];

  // Resize handle drag state
  let resizeDrag: {
    handle: ResizeHandle;
    startScreenX: number;
    startScreenY: number;
    origWidth: number;
    origHeight: number;
  } | null = null;

  const MIN_BOARD_SIZE = 5_000_000; // 5mm minimum in nm

  // Wheel zoom (zoom to cursor position)
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    // Zoom in on scroll up, out on scroll down
    const factor = e.deltaY < 0 ? 1.15 : 0.87;
    state.viewport = zoomAtPoint(state.viewport, x, y, factor);
    state.dirty = true;
    state.onViewportChange(state.viewport);
  }, { passive: false });

  // Pointer Events for two-finger touchpad/touchscreen pan
  canvas.addEventListener('pointerdown', (e) => {
    pointerCache.push({
      pointerId: e.pointerId,
      clientX: e.clientX,
      clientY: e.clientY,
    });
  });

  canvas.addEventListener('pointermove', (e) => {
    // Find this pointer in cache
    const index = pointerCache.findIndex(p => p.pointerId === e.pointerId);
    if (index === -1) return;

    // If exactly 2 pointers, perform two-finger pan
    if (pointerCache.length === 2) {
      const cached = pointerCache[index];
      const dx = e.clientX - cached.clientX;
      const dy = e.clientY - cached.clientY;

      // Half delta since both fingers contribute to pan
      state.viewport = pan(state.viewport, dx / 2, dy / 2);
      state.dirty = true;
      state.onViewportChange(state.viewport);
    }

    // Update cached position
    pointerCache[index].clientX = e.clientX;
    pointerCache[index].clientY = e.clientY;
  });

  // Shared cleanup function for pointer removal
  const removePointer = (e: PointerEvent) => {
    const index = pointerCache.findIndex(p => p.pointerId === e.pointerId);
    if (index !== -1) {
      pointerCache.splice(index, 1);
    }
  };

  canvas.addEventListener('pointerup', removePointer);
  canvas.addEventListener('pointercancel', removePointer);
  canvas.addEventListener('pointerout', removePointer);
  canvas.addEventListener('pointerleave', removePointer);

  // Middle-click pan OR Ctrl+left-click pan (for laptops without middle button)
  // Also: left-click on resize handle starts board resize drag
  canvas.addEventListener('mousedown', (e) => {
    // Resize handle drag (left-click, not during routing)
    if (e.button === 0 && !e.ctrlKey && state.routing.mode !== 'routing' && state.snapshot?.board) {
      const rect = canvas.getBoundingClientRect();
      const sx = e.clientX - rect.left;
      const sy = e.clientY - rect.top;
      const handle = hitTestResizeHandle(state.viewport, state.snapshot.board.width_nm, state.snapshot.board.height_nm, sx, sy);
      if (handle) {
        resizeDrag = {
          handle,
          startScreenX: e.clientX,
          startScreenY: e.clientY,
          origWidth: state.snapshot.board.width_nm,
          origHeight: state.snapshot.board.height_nm,
        };
        state.activeResizeHandle = handle;
        state.dirty = true;
        canvas.style.cursor = resizeHandleCursor(handle);
        e.preventDefault();
        return; // Don't fall through to pan
      }
    }

    if (e.button === 1 || (e.button === 0 && e.ctrlKey)) {
      state.isPanning = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      e.preventDefault();
      canvas.style.cursor = 'grabbing';
    }
  });

  canvas.addEventListener('mousemove', (e) => {
    // Resize handle drag
    if (resizeDrag && state.snapshot?.board) {
      const dxScreen = e.clientX - resizeDrag.startScreenX;
      const dyScreen = e.clientY - resizeDrag.startScreenY;
      // Convert screen delta to world delta (Y is inverted)
      const dxWorld = dxScreen / state.viewport.scale;
      const dyWorld = -dyScreen / state.viewport.scale; // invert for world coords

      let newW = resizeDrag.origWidth;
      let newH = resizeDrag.origHeight;
      const h = resizeDrag.handle;

      // East handles: width increases with rightward drag
      if (h === 'e' || h === 'ne' || h === 'se') {
        newW = resizeDrag.origWidth + dxWorld;
      }
      // West handles: width increases with leftward drag
      if (h === 'w' || h === 'nw' || h === 'sw') {
        newW = resizeDrag.origWidth - dxWorld;
      }
      // North handles: height increases with upward drag (negative screen dy → positive world dy)
      if (h === 'n' || h === 'nw' || h === 'ne') {
        newH = resizeDrag.origHeight + dyWorld;
      }
      // South handles: height increases with downward drag
      if (h === 's' || h === 'sw' || h === 'se') {
        newH = resizeDrag.origHeight - dyWorld;
      }

      // Clamp to minimum
      newW = Math.max(MIN_BOARD_SIZE, Math.round(newW));
      newH = Math.max(MIN_BOARD_SIZE, Math.round(newH));

      // Live-preview: update board size via engine directly (will push undo on mouseup)
      if (state.engine) {
        state.engine.set_board_size(newW, newH);
        // Update snapshot for re-render
        state.snapshot = state.engine.get_snapshot();
      }
      state.dirty = true;
      return;
    }

    if (state.isPanning) {
      const dx = e.clientX - state.lastX;
      const dy = e.clientY - state.lastY;
      state.viewport = pan(state.viewport, dx, dy);
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      state.dirty = true;
      state.onViewportChange(state.viewport);
    }
  });

  canvas.addEventListener('mouseup', () => {
    // Finish resize drag — push undo command with original → final dimensions
    if (resizeDrag && state.snapshot?.board) {
      const finalW = state.snapshot.board.width_nm;
      const finalH = state.snapshot.board.height_nm;
      // Only push undo if dimensions actually changed
      if (finalW !== resizeDrag.origWidth || finalH !== resizeDrag.origHeight) {
        // Revert to original so the undo command's execute() applies the change
        if (state.engine) {
          state.engine.set_board_size(resizeDrag.origWidth, resizeDrag.origHeight);
        }
        if (state.onBoardResize) {
          state.onBoardResize(resizeDrag.origWidth, resizeDrag.origHeight, finalW, finalH);
        }
      }
      resizeDrag = null;
      state.activeResizeHandle = null;
      canvas.style.cursor = 'default';
      state.dirty = true;
    }
    if (state.isPanning) {
      state.isPanning = false;
      canvas.style.cursor = 'default';
    }
  });

  canvas.addEventListener('mouseleave', () => {
    // Cancel resize on leave — revert to original
    if (resizeDrag) {
      if (state.engine) {
        state.engine.set_board_size(resizeDrag.origWidth, resizeDrag.origHeight);
        state.snapshot = state.engine.get_snapshot();
      }
      resizeDrag = null;
      state.activeResizeHandle = null;
      state.dirty = true;
    }
    if (state.isPanning) {
      state.isPanning = false;
      canvas.style.cursor = 'default';
    }
  });

  // --- DRC preview checker (debounced, used during routing) ---
  let drcChecker: ReturnType<typeof createDrcPreviewChecker> | null = null;

  function ensureDrcChecker(): ReturnType<typeof createDrcPreviewChecker> {
    if (!drcChecker && state.engine) {
      drcChecker = createDrcPreviewChecker(state.engine, 100);
      drcChecker.onViolations((violations) => {
        state.routing = setDrcViolations(state.routing, violations);
        state.onRoutingChange(state.routing);
        state.dirty = true;
      });
    }
    return drcChecker!;
  }

  // Pad hit tolerance — generous for easy targeting (1mm in nm, plus pixel tolerance)
  const PAD_HIT_TOLERANCE_NM = 500_000; // 0.5mm extra

  // Left-click selection (but not if Ctrl held - that's pan)
  canvas.addEventListener('click', (e) => {
    if (e.button !== 0 || e.ctrlKey) return; // Left click only, no Ctrl

    const rect = canvas.getBoundingClientRect();
    const screenX = e.clientX - rect.left;
    const screenY = e.clientY - rect.top;
    const [worldX, worldY] = screenToWorld(state.viewport, screenX, screenY);

    // ---- Routing state machine: click handling ----
    if (state.routing.mode === 'routing') {
      // While routing: check if we clicked a pad to complete, or empty space for waypoint
      const padHit = hitTestPad(state.snapshot, worldX, worldY, PAD_HIT_TOLERANCE_NM);

      if (padHit) {
        // Complete the route
        const result = completeRoute(state.routing, padHit);
        if (result && state.engine) {
          // Build flat segment array
          const flat: number[] = [];
          for (const s of result.segments) {
            flat.push(Math.round(s.start_x), Math.round(s.start_y), Math.round(s.end_x), Math.round(s.end_y));
          }
          if (state.onTraceAdd) {
            // Route through undo stack
            state.onTraceAdd(result.netName, result.layer, result.width, flat);
          } else {
            // Fallback: direct engine call
            const traceId = state.engine.add_trace(result.netName, result.layer, result.width, flat);
            if (traceId !== 0xFFFFFFFF) {
              console.log(`[Route] Trace added: id=${traceId} net=${result.netName}`);
              state.engine.run_drc_incremental();
            } else {
              console.warn('[Route] Failed to add trace');
            }
          }
        }
        // Reset to idle (preserve grid snap settings)
        const prevGridSnap = state.routing.gridSnapEnabled;
        const prevGridSpacing = state.routing.gridSpacing;
        state.routing = { ...createRoutingState(), gridSnapEnabled: prevGridSnap, gridSpacing: prevGridSpacing };
        if (drcChecker) drcChecker.cancel();
        state.onRoutingChange(state.routing);
        state.dirty = true;
        return;
      }

      // No pad hit — add waypoint
      state.routing = addWaypoint(state.routing);
      state.onRoutingChange(state.routing);
      state.dirty = true;
      return;
    }

    // ---- Idle mode: check pads first (to start routing), then traces, then components ----

    // Hit-test pads to start routing
    const padHit = hitTestPad(state.snapshot, worldX, worldY, PAD_HIT_TOLERANCE_NM);
    if (padHit && padHit.netName) {
      state.routing = startRoute(state.routing, padHit);
      ensureDrcChecker();
      state.onRoutingChange(state.routing);
      state.dirty = true;
      return;
    }

    // Try trace hit-test
    const hit = hitTestTrace(state.snapshot, state.viewport, screenX, screenY);
    if (hit) {
      state.selectedTraceId = hit.trace.id;
      state.onTraceSelect(hit.trace.id, e.clientX, e.clientY);
      console.log('[Trace] Selected:', hit.trace.net_name, 'id:', hit.trace.id, 'seg:', hit.segmentIndex);
      state.dirty = true;
      return;
    }

    // No trace hit — deselect trace and fall through to component selection
    if (state.selectedTraceId !== null) {
      state.selectedTraceId = null;
      state.onTraceSelect(null, 0, 0);
      state.dirty = true;
    }

    state.onSelect(worldX, worldY);
  });

  // Hover tracking for traces + routing preview + resize handles (rAF-guarded)
  let hoverRafPending = false;
  canvas.addEventListener('mousemove', (e) => {
    if (state.isPanning || resizeDrag || hoverRafPending) return;

    hoverRafPending = true;
    requestAnimationFrame(() => {
      hoverRafPending = false;
      const rect = canvas.getBoundingClientRect();
      const screenX = e.clientX - rect.left;
      const screenY = e.clientY - rect.top;
      const [worldX, worldY] = screenToWorld(state.viewport, screenX, screenY);

      // --- Routing preview update ---
      if (state.routing.mode === 'routing') {
        state.routing = updatePreview(state.routing, { x: worldX, y: worldY });
        state.onRoutingChange(state.routing);

        // Schedule debounced DRC check
        const checker = ensureDrcChecker();
        if (checker) checker.check(state.routing);

        state.dirty = true;
        canvas.style.cursor = 'crosshair';
        return;
      }

      // --- Resize handle hover cursor ---
      if (state.snapshot?.board) {
        const handle = hitTestResizeHandle(state.viewport, state.snapshot.board.width_nm, state.snapshot.board.height_nm, screenX, screenY);
        if (handle) {
          canvas.style.cursor = resizeHandleCursor(handle);
          // Still update trace hover to clear if needed
          if (state.hoveredTraceId != null) {
            state.hoveredTraceId = null;
            state.onTraceHover(null);
            state.dirty = true;
          }
          return;
        }
      }

      // --- Normal hover for traces ---
      const hit = hitTestTrace(state.snapshot, state.viewport, screenX, screenY);
      const newHovered = hit ? hit.trace.id : null;

      if (newHovered !== state.hoveredTraceId) {
        state.hoveredTraceId = newHovered;
        state.onTraceHover(newHovered);
        state.dirty = true;

        // Update cursor
        canvas.style.cursor = newHovered != null ? 'pointer' : 'default';
      }
    });
  });

  canvas.addEventListener('mouseleave', () => {
    if (state.hoveredTraceId !== null) {
      state.hoveredTraceId = null;
      state.onTraceHover(null);
      state.dirty = true;
    }
  });

  // Prevent context menu on right-click (reserve for future)
  canvas.addEventListener('contextmenu', (e) => e.preventDefault());
}

/**
 * Create initial interaction state
 */
export function createInteractionState(
  viewport: Viewport,
  onSelect: (x_nm: number, y_nm: number) => void,
  onViewportChange: (vp: Viewport) => void
): InteractionState {
  return {
    viewport,
    isPanning: false,
    lastX: 0,
    lastY: 0,
    dirty: false,
    onSelect,
    onViewportChange,
    snapshot: null,
    selectedTraceId: null,
    hoveredTraceId: null,
    onTraceSelect: () => {},
    onTraceHover: () => {},
    routing: createRoutingState(),
    engine: null,
    onRoutingChange: () => {},
  };
}

/**
 * Canvas 2D rendering functions for PCB visualization
 * Professional-quality renderer with LOD, per-pad net highlighting,
 * component body outlines, pad pin numbers, net labels, and drill marks.
 */

import type { BoardSnapshot, ComponentInfo, PadInfo, ViolationInfo, TraceInfo, ViaInfo, RatsnestInfo } from './types';
import type { Viewport } from './viewport';
import type { RoutingState } from './routing';
import type { RenderConfig } from './render-config';
import { LodTier, getLodTier, createDefaultRenderConfig } from './render-config';
import { worldToScreen, screenToWorld } from './viewport';
import { LAYER_COLORS, getPadColor, getTraceColor, getThemeColors, netColor, brightenColor, colorWithAlpha, type LayerVisibility } from './layers';

export interface RenderState {
  snapshot: BoardSnapshot | null;
  viewport: Viewport;
  layers: LayerVisibility;
  selectedRefdes: string | null;
  showViolations: boolean;
  showRatsnest: boolean;
  colorByNet: boolean;
  selectedTraceId: number | null;
  hoveredTraceId: number | null;
  /** Screen position for the net label tooltip (set by interaction layer) */
  labelPosition: { x: number; y: number } | null;
  /** Active routing state (null when not routing) */
  routing: RoutingState | null;
  /** Net name to highlight (all traces/pads on this net glow, others dim) */
  highlightedNet: string | null;
  /** Currently dragged resize handle (for visual feedback) */
  activeResizeHandle?: ResizeHandle | null;
  /** Render configuration (colors, fonts, LOD thresholds) */
  renderConfig?: RenderConfig;
  /** Pad-to-net lookup: "refdes.pin" → net name */
  padNetMap?: Map<string, string>;
}

/** Diagnostic surface exposed on window for E2E and debugging */
export interface RenderDiag {
  lodTier: LodTier;
  padNetMapSize: number;
  lastFrameMs: number;
  textElementsDrawn: number;
  highlightedNet: string | null;
}

// Module-level counter for text elements drawn per frame
let _textElementsDrawn = 0;

/**
 * Main render function - draws entire board state
 */
export function render(ctx: CanvasRenderingContext2D, state: RenderState): void {
  const frameStart = performance.now();
  _textElementsDrawn = 0;

  const { snapshot, viewport, layers, selectedRefdes, showViolations, showRatsnest } = state;
  const config = state.renderConfig ?? createDefaultRenderConfig();
  const padNetMap = state.padNetMap ?? new Map<string, string>();
  const lodTier = getLodTier(viewport.scale, config);

  // Get theme-dependent colors
  const themeColors = getThemeColors();

  // Clear canvas with background color
  ctx.fillStyle = themeColors.background;
  ctx.fillRect(0, 0, viewport.width, viewport.height);

  if (!snapshot || !snapshot.board) {
    drawEmptyState(ctx, viewport, themeColors);
    _updateDiag(lodTier, padNetMap.size, performance.now() - frameStart, state.highlightedNet);
    return;
  }

  // Draw grid (behind everything)
  drawGrid(ctx, viewport, themeColors);

  // Draw board outline
  drawBoardOutline(ctx, viewport, snapshot.board.width_nm, snapshot.board.height_nm, themeColors);

  // Draw resize handles when not routing
  if (!state.routing || state.routing.mode !== 'routing') {
    drawResizeHandles(ctx, viewport, snapshot.board.width_nm, snapshot.board.height_nm, themeColors, state.activeResizeHandle ?? null);
  }

  // Draw traces by layer (bottom first, then top)
  if (snapshot.traces) {
    const { colorByNet, selectedTraceId, hoveredTraceId, highlightedNet } = state;
    // Bottom traces first
    for (const trace of snapshot.traces) {
      if (trace.layer === 'Bottom' && layers.bottomCopper) {
        drawTrace(ctx, viewport, trace, layers, colorByNet, selectedTraceId, hoveredTraceId, highlightedNet);
      }
    }
    // Top traces on top
    for (const trace of snapshot.traces) {
      if (trace.layer === 'Top' && layers.topCopper) {
        drawTrace(ctx, viewport, trace, layers, colorByNet, selectedTraceId, hoveredTraceId, highlightedNet);
      }
    }
    // Inner layers
    for (const trace of snapshot.traces) {
      if (trace.layer !== 'Top' && trace.layer !== 'Bottom') {
        drawTrace(ctx, viewport, trace, layers, colorByNet, selectedTraceId, hoveredTraceId, highlightedNet);
      }
    }
  }

  // Draw components (pads, body outlines, drill marks)
  for (const comp of snapshot.components) {
    const isSelected = comp.refdes === selectedRefdes;
    drawComponent(ctx, viewport, comp, layers, isSelected, themeColors, state.highlightedNet, config, lodTier, padNetMap);
  }

  // Draw vias on top of traces but below ratsnest
  if (snapshot.vias) {
    for (const via of snapshot.vias) {
      if (layers.topCopper || layers.bottomCopper) {
        drawVia(ctx, viewport, via, themeColors);
      }
    }
  }

  // Draw ratsnest on top of everything (except violations)
  if (showRatsnest && snapshot.ratsnest) {
    for (const line of snapshot.ratsnest) {
      drawRatsnest(ctx, viewport, line);
    }
  }

  // Draw violations on top of everything
  if (showViolations && snapshot.violations) {
    for (const violation of snapshot.violations) {
      drawViolation(ctx, viewport, violation);
    }
  }

  // ---- TEXT PASS (after all shapes, for readability) ----

  // Refdes labels (LOD ≥ Medium)
  if (lodTier >= LodTier.Medium) {
    for (const comp of snapshot.components) {
      const isSelected = comp.refdes === selectedRefdes;
      drawRefdes(ctx, viewport, comp, isSelected, themeColors, config);
    }
  }

  // Pad pin numbers (LOD ≥ Close)
  if (lodTier >= LodTier.Close) {
    for (const comp of snapshot.components) {
      drawPadNumbers(ctx, viewport, comp, layers, config);
    }
  }

  // Net labels on traces (LOD ≥ Close)
  if (lodTier >= LodTier.Close && snapshot.traces) {
    drawTraceNetLabels(ctx, viewport, snapshot.traces, layers, config);
  }

  // Draw routing preview (dashed trace + DRC markers)
  if (state.routing && state.routing.mode === 'routing') {
    drawRoutingPreview(ctx, viewport, state.routing);
  }

  // Draw net label for selected trace
  if (state.selectedTraceId != null && state.labelPosition && snapshot.traces) {
    const selectedTrace = snapshot.traces.find(t => t.id === state.selectedTraceId);
    if (selectedTrace) {
      drawNetLabel(ctx, state.labelPosition.x, state.labelPosition.y, selectedTrace);
    }
  }

  const frameMs = performance.now() - frameStart;
  _updateDiag(lodTier, padNetMap.size, frameMs, state.highlightedNet);

  // Warn about slow frames
  if (frameMs > 16) {
    console.warn(`[renderer] Slow frame: ${frameMs.toFixed(1)}ms (LOD=${LodTier[lodTier]}, text=${_textElementsDrawn})`);
  }
}

/** Update the global diagnostic surface */
function _updateDiag(lodTier: LodTier, padNetMapSize: number, lastFrameMs: number, highlightedNet: string | null): void {
  const diag: RenderDiag = {
    lodTier,
    padNetMapSize,
    lastFrameMs,
    textElementsDrawn: _textElementsDrawn,
    highlightedNet,
  };
  (window as any).__renderDiag = diag;
}

// ---------------------------------------------------------------------------
// Empty state
// ---------------------------------------------------------------------------

function drawEmptyState(ctx: CanvasRenderingContext2D, viewport: Viewport, themeColors: ReturnType<typeof getThemeColors>): void {
  ctx.fillStyle = themeColors.empty_text;
  ctx.font = '16px system-ui';
  ctx.textAlign = 'center';
  ctx.fillText('No board loaded', viewport.width / 2, viewport.height / 2);
}

// ---------------------------------------------------------------------------
// Grid
// ---------------------------------------------------------------------------

function drawGrid(ctx: CanvasRenderingContext2D, vp: Viewport, themeColors: ReturnType<typeof getThemeColors>): void {
  const gridSpacing = 1_000_000; // 1mm
  const screenSpacing = gridSpacing * vp.scale;
  if (screenSpacing < 10) return;

  ctx.strokeStyle = themeColors.grid;
  ctx.lineWidth = 1;

  const [minX, maxY] = screenToWorld(vp, 0, 0);
  const [maxX, minY] = screenToWorld(vp, vp.width, vp.height);

  const startX = Math.floor(minX / gridSpacing) * gridSpacing;
  const startY = Math.floor(minY / gridSpacing) * gridSpacing;

  ctx.beginPath();
  for (let x = startX; x <= maxX; x += gridSpacing) {
    const [sx] = worldToScreen(vp, x, 0);
    ctx.moveTo(sx, 0);
    ctx.lineTo(sx, vp.height);
  }
  for (let y = startY; y <= maxY; y += gridSpacing) {
    const [, sy] = worldToScreen(vp, 0, y);
    ctx.moveTo(0, sy);
    ctx.lineTo(vp.width, sy);
  }
  ctx.stroke();
}

// ---------------------------------------------------------------------------
// Board outline + resize handles
// ---------------------------------------------------------------------------

function drawBoardOutline(ctx: CanvasRenderingContext2D, vp: Viewport, width: number, height: number, themeColors: ReturnType<typeof getThemeColors>): void {
  const [x0, y0] = worldToScreen(vp, 0, 0);
  const [x1, y1] = worldToScreen(vp, width, height);
  ctx.strokeStyle = themeColors.board_outline;
  ctx.lineWidth = 2;
  ctx.strokeRect(x0, y1, x1 - x0, y0 - y1);
}

export type ResizeHandle =
  | 'nw' | 'n' | 'ne'
  | 'w'  |       'e'
  | 'sw' | 's' | 'se';

const HANDLE_SIZE = 8;

export function drawResizeHandles(
  ctx: CanvasRenderingContext2D,
  vp: Viewport,
  width: number,
  height: number,
  themeColors: ReturnType<typeof getThemeColors>,
  activeHandle: ResizeHandle | null,
): void {
  const handles = computeHandlePositions(vp, 0, 0, width, height);
  const hs = HANDLE_SIZE;
  for (const h of handles) {
    const isActive = h.id === activeHandle;
    ctx.fillStyle = isActive ? '#FF6600' : themeColors.board_outline;
    ctx.strokeStyle = themeColors.background;
    ctx.lineWidth = 1;
    ctx.fillRect(h.cx - hs, h.cy - hs, hs * 2, hs * 2);
    ctx.strokeRect(h.cx - hs, h.cy - hs, hs * 2, hs * 2);
  }
}

function computeHandlePositions(
  vp: Viewport, originX: number, originY: number, width: number, height: number,
): { id: ResizeHandle; cx: number; cy: number }[] {
  const [x0, y0] = worldToScreen(vp, originX, originY);
  const [x1, y1] = worldToScreen(vp, width, height);
  const left = x0, right = x1, top = y1, bottom = y0;
  const midX = (left + right) / 2, midY = (top + bottom) / 2;
  return [
    { id: 'nw', cx: left,  cy: top },
    { id: 'n',  cx: midX,  cy: top },
    { id: 'ne', cx: right, cy: top },
    { id: 'w',  cx: left,  cy: midY },
    { id: 'e',  cx: right, cy: midY },
    { id: 'sw', cx: left,  cy: bottom },
    { id: 's',  cx: midX,  cy: bottom },
    { id: 'se', cx: right, cy: bottom },
  ];
}

export function hitTestResizeHandle(
  vp: Viewport, boardWidth: number, boardHeight: number, screenX: number, screenY: number,
): ResizeHandle | null {
  const handles = computeHandlePositions(vp, 0, 0, boardWidth, boardHeight);
  const tolerance = HANDLE_SIZE + 4;
  for (const h of handles) {
    if (Math.abs(screenX - h.cx) <= tolerance && Math.abs(screenY - h.cy) <= tolerance) {
      return h.id;
    }
  }
  return null;
}

export function resizeHandleCursor(handle: ResizeHandle): string {
  switch (handle) {
    case 'n': case 's': return 'ns-resize';
    case 'e': case 'w': return 'ew-resize';
    case 'nw': case 'se': return 'nwse-resize';
    case 'ne': case 'sw': return 'nesw-resize';
  }
}

// ---------------------------------------------------------------------------
// Violations
// ---------------------------------------------------------------------------

function drawViolation(ctx: CanvasRenderingContext2D, vp: Viewport, violation: ViolationInfo): void {
  const [sx, sy] = worldToScreen(vp, violation.x_nm, violation.y_nm);
  const radius = 15;
  const innerRadius = 10;

  ctx.beginPath();
  ctx.arc(sx, sy, radius, 0, Math.PI * 2);
  ctx.strokeStyle = LAYER_COLORS.violation_ring;
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(sx, sy, innerRadius, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255, 0, 0, 0.3)';
  ctx.fill();
}

// ---------------------------------------------------------------------------
// Traces
// ---------------------------------------------------------------------------

function tracePolyline(ctx: CanvasRenderingContext2D, vp: Viewport, trace: TraceInfo): void {
  ctx.beginPath();
  const firstSeg = trace.segments[0];
  const [startX, startY] = worldToScreen(vp, firstSeg.start_x, firstSeg.start_y);
  ctx.moveTo(startX, startY);
  for (const seg of trace.segments) {
    const [endX, endY] = worldToScreen(vp, seg.end_x, seg.end_y);
    ctx.lineTo(endX, endY);
  }
}

function drawTrace(
  ctx: CanvasRenderingContext2D, vp: Viewport, trace: TraceInfo, layers: LayerVisibility,
  colorByNet: boolean, selectedTraceId: number | null, hoveredTraceId: number | null,
  highlightedNet: string | null,
): void {
  if (trace.segments.length === 0) return;

  const isHighlightedNet = highlightedNet != null && trace.net_name === highlightedNet;
  const isDimmed = highlightedNet != null && !isHighlightedNet;

  let color: string | null;
  if (colorByNet && trace.net_name) {
    const layerVisible = getTraceColor(trace.layer, layers) !== null;
    if (!layerVisible) return;
    color = netColor(trace.net_name);
  } else {
    color = getTraceColor(trace.layer, layers);
  }
  if (!color) return;

  if (isDimmed) {
    color = colorWithAlpha(color, 0.15);
  }

  const isSelected = trace.id === selectedTraceId;
  const isHovered = trace.id === hoveredTraceId && !isSelected;
  const baseLineWidth = trace.width * vp.scale;
  if (baseLineWidth < 0.5) return;

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Selection glow
  if (isSelected) {
    ctx.strokeStyle = colorWithAlpha(brightenColor(color, 25), 0.35);
    ctx.lineWidth = baseLineWidth * 2.5;
    tracePolyline(ctx, vp, trace);
    ctx.stroke();
  }

  // Net highlight glow
  if (isHighlightedNet && !isSelected) {
    ctx.strokeStyle = colorWithAlpha(brightenColor(color, 20), 0.3);
    ctx.lineWidth = baseLineWidth * 2.0;
    tracePolyline(ctx, vp, trace);
    ctx.stroke();
  }

  // Main stroke
  const drawColor = isSelected ? brightenColor(color, 20) : isHighlightedNet ? brightenColor(color, 15) : color;
  const lineWidth = isSelected ? baseLineWidth * 1.5 : isHighlightedNet ? baseLineWidth * 1.2 : baseLineWidth;
  ctx.strokeStyle = drawColor;
  ctx.lineWidth = lineWidth;
  tracePolyline(ctx, vp, trace);
  ctx.stroke();

  // Hover overlay
  if (isHovered) {
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.25)';
    ctx.lineWidth = baseLineWidth;
    tracePolyline(ctx, vp, trace);
    ctx.stroke();
  }

  // Locked indicator
  if (trace.locked && baseLineWidth > 2) {
    ctx.save();
    ctx.setLineDash([5, 5]);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)';
    ctx.lineWidth = Math.max(1, baseLineWidth * 0.3);
    tracePolyline(ctx, vp, trace);
    ctx.stroke();
    ctx.restore();
  }
}

// ---------------------------------------------------------------------------
// Trace net labels (text pass, LOD ≥ Close)
// ---------------------------------------------------------------------------

function drawTraceNetLabels(
  ctx: CanvasRenderingContext2D, vp: Viewport, traces: TraceInfo[],
  layers: LayerVisibility, config: RenderConfig,
): void {
  // World-space label size: 0.5mm
  const labelWorldSize = 500_000;
  const fontSize = Math.min(14, Math.max(8, labelWorldSize * vp.scale));
  ctx.font = `${fontSize.toFixed(1)}px system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  for (const trace of traces) {
    if (!trace.net_name || trace.segments.length === 0) continue;
    // Check layer visibility
    if (getTraceColor(trace.layer, layers) === null) continue;

    // Find longest segment
    let longestLen = 0;
    let longestIdx = 0;
    for (let i = 0; i < trace.segments.length; i++) {
      const seg = trace.segments[i];
      const [sx1, sy1] = worldToScreen(vp, seg.start_x, seg.start_y);
      const [sx2, sy2] = worldToScreen(vp, seg.end_x, seg.end_y);
      const len = Math.hypot(sx2 - sx1, sy2 - sy1);
      if (len > longestLen) {
        longestLen = len;
        longestIdx = i;
      }
    }

    if (longestLen < config.fontConfig.netLabelMinSegmentPx) continue;

    const seg = trace.segments[longestIdx];
    const [sx1, sy1] = worldToScreen(vp, seg.start_x, seg.start_y);
    const [sx2, sy2] = worldToScreen(vp, seg.end_x, seg.end_y);
    const midX = (sx1 + sx2) / 2;
    const midY = (sy1 + sy2) / 2;

    // Rotate along segment
    let angle = Math.atan2(sy2 - sy1, sx2 - sx1);
    // Keep text upright (avoid upside-down text)
    if (angle > Math.PI / 2) angle -= Math.PI;
    if (angle < -Math.PI / 2) angle += Math.PI;

    ctx.save();
    ctx.translate(midX, midY);
    ctx.rotate(angle);

    // Background pill for readability
    const textMetrics = ctx.measureText(trace.net_name);
    const padX = 3;
    const padY = 2;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
    ctx.fillRect(
      -textMetrics.width / 2 - padX,
      -fontSize / 2 - padY,
      textMetrics.width + padX * 2,
      fontSize + padY * 2,
    );

    ctx.fillStyle = '#FFFFFF';
    ctx.fillText(trace.net_name, 0, 0);
    ctx.restore();

    _textElementsDrawn++;
  }
}

// ---------------------------------------------------------------------------
// Net label tooltip (for selected trace)
// ---------------------------------------------------------------------------

function drawNetLabel(ctx: CanvasRenderingContext2D, screenX: number, screenY: number, trace: TraceInfo): void {
  const widthMm = (trace.width / 1_000_000).toFixed(2);
  const label = `${trace.net_name} — ${widthMm}mm`;

  ctx.font = '12px system-ui, sans-serif';
  const metrics = ctx.measureText(label);
  const padX = 8;
  const boxW = metrics.width + padX * 2;
  const boxH = 20;
  const offsetX = 15;
  const offsetY = -25;
  const x = screenX + offsetX;
  const y = screenY + offsetY;

  ctx.fillStyle = 'rgba(0, 0, 0, 0.75)';
  ctx.beginPath();
  ctx.roundRect(x, y, boxW, boxH, 4);
  ctx.fill();

  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText(label, x + padX, y + boxH / 2);
}

// ---------------------------------------------------------------------------
// Vias
// ---------------------------------------------------------------------------

function drawVia(ctx: CanvasRenderingContext2D, vp: Viewport, via: ViaInfo, themeColors: ReturnType<typeof getThemeColors>): void {
  const [sx, sy] = worldToScreen(vp, via.x, via.y);
  const outerRadius = (via.outer_diameter * vp.scale) / 2;
  const drillRadius = (via.drill * vp.scale) / 2;
  if (outerRadius < 1) return;

  ctx.beginPath();
  ctx.arc(sx, sy, outerRadius, 0, Math.PI * 2);
  ctx.fillStyle = LAYER_COLORS.via;
  ctx.fill();

  if (drillRadius > 0.5) {
    ctx.beginPath();
    ctx.arc(sx, sy, drillRadius, 0, Math.PI * 2);
    ctx.fillStyle = themeColors.background;
    ctx.fill();
  }
}

// ---------------------------------------------------------------------------
// Ratsnest
// ---------------------------------------------------------------------------

function drawRatsnest(ctx: CanvasRenderingContext2D, vp: Viewport, line: RatsnestInfo): void {
  const [startX, startY] = worldToScreen(vp, line.start_x, line.start_y);
  const [endX, endY] = worldToScreen(vp, line.end_x, line.end_y);

  ctx.save();
  ctx.strokeStyle = LAYER_COLORS.ratsnest;
  ctx.lineWidth = 1;
  ctx.setLineDash([5, 3]);
  ctx.beginPath();
  ctx.moveTo(startX, startY);
  ctx.lineTo(endX, endY);
  ctx.stroke();
  ctx.restore();
}

// ---------------------------------------------------------------------------
// Components — pad drawing, body outlines, drill marks
// ---------------------------------------------------------------------------

function drawComponent(
  ctx: CanvasRenderingContext2D, vp: Viewport, comp: ComponentInfo,
  layers: LayerVisibility, isSelected: boolean,
  themeColors: ReturnType<typeof getThemeColors>,
  highlightedNet: string | null,
  config: RenderConfig, lodTier: LodTier,
  padNetMap: Map<string, string>,
): void {
  // Draw pads
  for (const pad of comp.pads) {
    drawPad(ctx, vp, comp.x_nm, comp.y_nm, comp.rotation_mdeg, pad, layers, isSelected, themeColors, highlightedNet, comp.refdes, padNetMap, lodTier);
  }

  // Component body outline (LOD ≥ Medium, non-zero body dimensions)
  if (lodTier >= LodTier.Medium && comp.body_width_nm > 0 && comp.body_height_nm > 0) {
    drawBodyOutline(ctx, vp, comp, config);
  }
}

// ---------------------------------------------------------------------------
// Component body outline (silkscreen)
// ---------------------------------------------------------------------------

function drawBodyOutline(
  ctx: CanvasRenderingContext2D, vp: Viewport,
  comp: ComponentInfo, config: RenderConfig,
): void {
  const [sx, sy] = worldToScreen(vp, comp.x_nm, comp.y_nm);
  const w = comp.body_width_nm * vp.scale;
  const h = comp.body_height_nm * vp.scale;
  const radians = (comp.rotation_mdeg / 1000) * (Math.PI / 180);

  ctx.save();
  ctx.translate(sx, sy);
  ctx.rotate(-radians); // screen Y-down
  ctx.strokeStyle = config.layerColors.silkscreen;
  ctx.lineWidth = 1.5;
  ctx.setLineDash([4, 3]); // dashed to distinguish from copper
  ctx.strokeRect(-w / 2, -h / 2, w, h);
  ctx.setLineDash([]);
  ctx.restore();
}

// ---------------------------------------------------------------------------
// Refdes text (text pass, LOD ≥ Medium)
// ---------------------------------------------------------------------------

function drawRefdes(
  ctx: CanvasRenderingContext2D, vp: Viewport,
  comp: ComponentInfo, isSelected: boolean,
  themeColors: ReturnType<typeof getThemeColors>,
  config: RenderConfig,
): void {
  const [sx, sy] = worldToScreen(vp, comp.x_nm, comp.y_nm);

  // World-space font size, clamped 8–24px
  const rawSize = config.fontConfig.refdesWorldSize * vp.scale;
  const fontSize = Math.min(24, Math.max(8, rawSize));

  ctx.fillStyle = isSelected ? '#FF6600' : themeColors.label;
  ctx.font = `bold ${fontSize.toFixed(1)}px system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'bottom';
  ctx.fillText(comp.refdes, sx, sy - 3);

  _textElementsDrawn++;
}

// ---------------------------------------------------------------------------
// Pad pin numbers (text pass, LOD ≥ Close)
// ---------------------------------------------------------------------------

function drawPadNumbers(
  ctx: CanvasRenderingContext2D, vp: Viewport,
  comp: ComponentInfo, layers: LayerVisibility,
  config: RenderConfig,
): void {
  const radians = (comp.rotation_mdeg / 1000) * (Math.PI / 180);
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);

  // Group pads by approximate font size to minimize ctx.font changes
  for (const pad of comp.pads) {
    if (!pad.number) continue;
    // Check visibility
    if (getPadColor(pad.layer_mask, layers) === null) continue;

    const padScreenW = pad.width_nm * vp.scale;
    if (padScreenW < config.fontConfig.padNumberMinScreenPx) continue;

    // Compute pad screen position
    const rotatedX = pad.x_nm * cos - pad.y_nm * sin;
    const rotatedY = pad.x_nm * sin + pad.y_nm * cos;
    const worldX = comp.x_nm + rotatedX;
    const worldY = comp.y_nm + rotatedY;
    const [sx, sy] = worldToScreen(vp, worldX, worldY);

    // Font size proportional to pad, clamped 8–18px
    const fontSize = Math.min(18, Math.max(8, padScreenW * 0.5));

    ctx.font = `${fontSize.toFixed(0)}px system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    // Use contrasting color: white on dark pads (copper colors are dark)
    ctx.fillStyle = '#FFFFFF';
    ctx.fillText(pad.number, sx, sy);

    _textElementsDrawn++;
  }
}

// ---------------------------------------------------------------------------
// Single pad
// ---------------------------------------------------------------------------

function drawPad(
  ctx: CanvasRenderingContext2D, vp: Viewport,
  compX: number, compY: number, rotationMdeg: number,
  pad: PadInfo, layers: LayerVisibility, isSelected: boolean,
  themeColors: ReturnType<typeof getThemeColors>,
  highlightedNet: string | null,
  compRefdes: string,
  padNetMap: Map<string, string>,
  lodTier: LodTier,
): void {
  let color = getPadColor(pad.layer_mask, layers);
  if (!color) return;

  // Per-pad net highlighting
  if (highlightedNet != null) {
    const padKey = `${compRefdes}.${pad.number}`;
    const padNet = padNetMap.get(padKey);
    if (padNet === highlightedNet) {
      // Glow: brighten the pad color
      color = brightenColor(color, 20);
    } else {
      // Dim pads not on the highlighted net
      color = colorWithAlpha(color, 0.15);
    }
  }

  // Compute pad world position with component rotation
  const radians = (rotationMdeg / 1000) * (Math.PI / 180);
  const cos = Math.cos(radians);
  const sin = Math.sin(radians);
  const rotatedX = pad.x_nm * cos - pad.y_nm * sin;
  const rotatedY = pad.x_nm * sin + pad.y_nm * cos;
  const worldX = compX + rotatedX;
  const worldY = compY + rotatedY;

  const [screenX, screenY] = worldToScreen(vp, worldX, worldY);
  const width = pad.width_nm * vp.scale;
  const height = pad.height_nm * vp.scale;
  if (width < 0.5 && height < 0.5) return;

  ctx.save();
  ctx.translate(screenX, screenY);
  ctx.rotate(-radians);

  // Glow ring for pads on the highlighted net
  if (highlightedNet != null) {
    const padKey = `${compRefdes}.${pad.number}`;
    const padNet = padNetMap.get(padKey);
    if (padNet === highlightedNet) {
      const glowColor = colorWithAlpha(brightenColor(getPadColor(pad.layer_mask, layers) ?? '#FFFFFF', 25), 0.35);
      ctx.fillStyle = glowColor;
      // Draw a slightly larger shape behind as glow
      const gw = width * 1.4;
      const gh = height * 1.4;
      switch (pad.shape) {
        case 'circle':
          ctx.beginPath();
          ctx.arc(0, 0, gw / 2, 0, Math.PI * 2);
          ctx.fill();
          break;
        default:
          ctx.fillRect(-gw / 2, -gh / 2, gw, gh);
          break;
      }
    }
  }

  ctx.fillStyle = isSelected ? '#FF6600' : color;

  switch (pad.shape) {
    case 'circle':
      ctx.beginPath();
      ctx.arc(0, 0, width / 2, 0, Math.PI * 2);
      ctx.fill();
      break;
    case 'rect':
      ctx.fillRect(-width / 2, -height / 2, width, height);
      break;
    case 'roundrect':
      drawRoundRect(ctx, -width / 2, -height / 2, width, height, Math.min(width, height) * 0.25);
      ctx.fill();
      break;
    case 'oblong':
      drawOblong(ctx, -width / 2, -height / 2, width, height);
      ctx.fill();
      break;
    default:
      ctx.fillRect(-width / 2, -height / 2, width, height);
  }

  // Drill hole for through-hole pads
  if (pad.drill_nm) {
    const drillRadius = pad.drill_nm * vp.scale / 2;
    if (drillRadius > 0.5) {
      ctx.fillStyle = themeColors.background;
      ctx.beginPath();
      ctx.arc(0, 0, drillRadius, 0, Math.PI * 2);
      ctx.fill();

      // Drill crosshair (LOD ≥ Medium) — drawn inside the drill hole
      if (lodTier >= LodTier.Medium && drillRadius > 2) {
        const crossLen = drillRadius * 0.7;
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(-crossLen, 0);
        ctx.lineTo(crossLen, 0);
        ctx.moveTo(0, -crossLen);
        ctx.lineTo(0, crossLen);
        ctx.stroke();
      }
    }
  }

  ctx.restore();
}

// ---------------------------------------------------------------------------
// Geometry helpers (pad shapes)
// ---------------------------------------------------------------------------

function drawRoundRect(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number): void {
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

function drawOblong(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number): void {
  const r = Math.min(w, h) / 2;
  drawRoundRect(ctx, x, y, w, h, r);
}

// ---------------------------------------------------------------------------
// Routing preview
// ---------------------------------------------------------------------------

function drawRoutingPreview(ctx: CanvasRenderingContext2D, vp: Viewport, routing: RoutingState): void {
  const color = routing.netName ? netColor(routing.netName) : '#00FF00';
  const lineWidth = routing.traceWidth * vp.scale;
  const drawWidth = Math.max(lineWidth, 2);

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  if (routing.committedSegments.length > 0) {
    ctx.strokeStyle = colorWithAlpha(color, 0.7);
    ctx.lineWidth = drawWidth;
    ctx.beginPath();
    const first = routing.committedSegments[0];
    const [sx, sy] = worldToScreen(vp, first.start_x, first.start_y);
    ctx.moveTo(sx, sy);
    for (const seg of routing.committedSegments) {
      const [ex, ey] = worldToScreen(vp, seg.end_x, seg.end_y);
      ctx.lineTo(ex, ey);
    }
    ctx.stroke();
  }

  if (routing.previewSegment) {
    const seg = routing.previewSegment;
    const [sx, sy] = worldToScreen(vp, seg.start_x, seg.start_y);
    const [ex, ey] = worldToScreen(vp, seg.end_x, seg.end_y);

    ctx.save();
    ctx.setLineDash([8, 4]);
    ctx.strokeStyle = colorWithAlpha(color, 0.8);
    ctx.lineWidth = drawWidth;
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.lineTo(ex, ey);
    ctx.stroke();
    ctx.restore();

    ctx.beginPath();
    ctx.arc(ex, ey, Math.max(4, drawWidth * 0.6), 0, Math.PI * 2);
    ctx.fillStyle = colorWithAlpha(color, 0.5);
    ctx.fill();
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.stroke();
  }

  const [ax, ay] = worldToScreen(vp, routing.anchorPoint.x, routing.anchorPoint.y);
  ctx.beginPath();
  ctx.arc(ax, ay, 5, 0, Math.PI * 2);
  ctx.fillStyle = '#FFFFFF';
  ctx.fill();
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.stroke();

  for (const v of routing.drcViolations) {
    const [vx, vy] = worldToScreen(vp, v.x_nm, v.y_nm);
    ctx.beginPath();
    ctx.arc(vx, vy, 12, 0, Math.PI * 2);
    ctx.strokeStyle = '#FF0000';
    ctx.lineWidth = 2.5;
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(vx, vy, 8, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 0, 0, 0.25)';
    ctx.fill();
  }

  if (routing.previewSegment) {
    const seg = routing.previewSegment;
    const [ex, ey] = worldToScreen(vp, seg.end_x, seg.end_y);
    ctx.font = '11px system-ui, sans-serif';
    ctx.fillStyle = 'rgba(255, 255, 255, 0.85)';
    ctx.textAlign = 'left';
    ctx.fillText(`${routing.snapAngle}°`, ex + 12, ey - 8);

    let label = routing.currentLayer;
    if (routing.netName) label = `${routing.netName} [${routing.currentLayer}]`;
    ctx.fillText(label, ex + 12, ey + 6);
  }
}

